class Solution
{
    int skip[10][10] = {};
    bool used[10] = {};
    int dfs(int last, int remaining)
    {
        if (remaining == 0) return 1;
        int ways = 0;
        for (int next = 1; next <= 9; ++next)
        {
            int middle = skip[last][next];
            if (!used[next] && (middle == 0 || used[middle]))
            {
                used[next] = true;
                ways += dfs(next, remaining - 1);
                used[next] = false;
            }
        }
        return ways;
    }
public:
    int numberOfPatterns(int m, int n)
    {
        memset(skip, 0, sizeof(skip));
        memset(used, 0, sizeof(used));
        skip[1][3] = skip[3][1] = 2;
        skip[1][7] = skip[7][1] = 4;
        skip[3][9] = skip[9][3] = 6;
        skip[7][9] = skip[9][7] = 8;
        skip[1][9] = skip[9][1] = 5;
        skip[3][7] = skip[7][3] = 5;
        skip[2][8] = skip[8][2] = 5;
        skip[4][6] = skip[6][4] = 5;
        int total = 0;
        for (int length = m; length <= n; ++length)
        {
            used[1] = true;
            total += 4 * dfs(1, length - 1);
            used[1] = false;
            used[2] = true;
            total += 4 * dfs(2, length - 1);
            used[2] = false;
            used[5] = true;
            total += dfs(5, length - 1);
            used[5] = false;
        }
        return total;
    }
};
